// Some portions generated by Claude

// Round-3 review of GH-6071 (client side): repository ids on Create, UTF-8 credentials on Connection, focus after a
// confirm dialog and leaving editor full screen. The browser behaviour is in e2e/tests/workbench-round3-forms.spec.js.
const test = require('node:test');
const assert = require('node:assert/strict');
const { createFormBrowserHarness } = require('./form-browser-harness.js');

const settle = () => new Promise((resolve) => setImmediate(resolve));

/** window.btoa as browsers have it: Latin-1 only. */
function latin1Btoa(value) {
    const text = String(value);
    if (/[^\u0000-ÿ]/.test(text)) {
        throw new Error('InvalidCharacterError: The string contains characters outside of the Latin1 range.');
    }
    return Buffer.from(text, 'latin1').toString('base64');
}

function createForm(harness, idValue) {
    const form = harness.registerElement('form', { attributes: { action: 'create' } });
    const cell = harness.registerElement('td');
    const id = harness.registerElement('input', {
        id: 'id', value: idValue, attributes: { 'data-field-role': 'repository-id' }
    });
    const create = harness.registerElement('input', { id: 'create', type: 'button' });
    cell.appendChild(id);
    form.appendChild(cell);
    form.appendChild(create);
    harness.document.body.appendChild(form);
    harness.loadScripts(['create.js']);
    harness.workbench.create.mount(harness.document.body);
    return { form, id, create };
}

const INVALID = (id) => `Repository ID '${id}' is not valid: use only the letters a-z and A-Z, digits, '-', '_', '.' and '@', and not only dots.`;

test('a repository id holds ASCII letters, digits, hyphens, underscores, dots and @, as the server accepts', () => {
    const harness = createFormBrowserHarness();
    harness.loadScripts(['create.js']);
    const problem = harness.context.workbench.create.idProblem;
    for (const id of ['memory', 'Repo_2.v-1', 'SYSTEM@localhost', '.hidden', 'a..b']) {
        assert.equal(problem(id), '', id);
    }
    assert.equal(problem(''), '', 'a form that opens without an id shows no error');
    assert.equal(problem('', true), 'Enter a repository ID.');
    for (const id of ['bad id/with slash', 'a?b#c', 'tab\there', 'café', 'smile😀', '.', '..']) {
        assert.equal(problem(id), INVALID(id), id);
    }
});

test('Create explains an id the server cannot use at the field, keeps Create disabled and checks nothing', async () => {
    const harness = createFormBrowserHarness();
    const { form, id, create } = createForm(harness, 'bad id');
    const error = harness.document.getElementById('repository-id-error');
    assert.ok(error, 'the explanation sits next to the field');
    assert.equal(error.hidden, false, 'an invalid id from the address is explained at once');
    assert.equal(error.textContent, INVALID('bad id'));
    assert.equal(create.disabled, true);

    harness.document.activeElement = null;
    harness.context.checkOverwrite();
    await settle();
    assert.equal(harness.ajaxRequests.length, 0, 'no existence check');
    assert.equal(form.submitCount, 0);
    assert.equal(harness.document.activeElement, id, 'the field takes focus to be corrected');
    assert.equal(id.getAttribute('aria-invalid'), 'true');
    assert.equal(id.getAttribute('aria-describedby'), 'repository-id-error');

    id.value = 'good-id';
    id.trigger('input');
    assert.equal(error.hidden, true);
    assert.equal(create.disabled, false);
    assert.ok(!id.getAttribute('aria-invalid'));
    assert.ok(!id.getAttribute('aria-describedby'));

    id.value = '';
    id.trigger('input');
    assert.equal(error.hidden, false);
    assert.equal(error.textContent, 'Enter a repository ID.');
    assert.equal(create.disabled, true);
});

test('Create asks the repository list, and falls back to the id information page with the id encoded', async () => {
    const harness = createFormBrowserHarness({ confirmResponses: [true] });
    const { form, id } = createForm(harness, 'SYSTEM@localhost');
    harness.context.checkOverwrite();
    const list = harness.ajaxRequests[0];
    assert.equal(list.options.url, '../NONE/repositories');
    assert.equal(list.options.dataType, 'json');
    assert.equal(list.options.headers.Accept, 'application/sparql-results+json');
    list.status(403);
    const info = harness.ajaxRequests[1];
    assert.equal(info.options.url, '../SYSTEM%40localhost/info');
    info.status(404);
    await settle();
    // A usable id, but not a lowercase one: the confirmation asks first and answers yes here.
    assert.equal(harness.confirms.length, 1);
    assert.match(harness.confirms[0], /Use this repository id\?/);
    assert.equal(form.submitCount, 1);
    assert.ok(!id.getAttribute('aria-invalid'));
});


test('a lookup that answers after the form was left asks nothing more', async () => {
    const harness = createFormBrowserHarness();
    const { form } = createForm(harness, 'new-id');
    let current = true;
    harness.context.workbench.router = {
        isRunning: () => true,
        captureFormOwner: () => ({ url: 'http://localhost/wb/repositories/NONE/create', isCurrent: () => current }),
        submit: (submitted) => submitted.submit()
    };
    harness.context.checkOverwrite();
    assert.equal(harness.ajaxRequests[0].options.url, 'http://localhost/wb/repositories/NONE/repositories');
    current = false;
    harness.ajaxRequests[0].status(403);
    await settle();
    assert.equal(harness.ajaxRequests.length, 1, 'no information page request for a form no longer shown');
    assert.equal(form.submitCount, 0);
});

test('Connection sends credentials with characters outside Latin-1 as UTF-8 base64', () => {
    const harness = createFormBrowserHarness({ window: { btoa: latin1Btoa } });
    const form = harness.registerElement('form', { id: 'server-form' });
    const user = harness.registerElement('input', { id: 'server-user', value: 'ålice' });
    const password = harness.registerElement('input', { id: 'server-password', value: 'pass✓' });
    form.appendChild(user);
    form.appendChild(password);
    harness.document.body.appendChild(form);
    harness.loadScripts(['server.js']);

    harness.context.changeServer({ target: password, preventDefault() { } });
    assert.equal(password.name, 'server-user-password');
    assert.equal(password.value, Buffer.from('ålice:pass✓', 'utf8').toString('base64'));
    assert.equal(form.submitCount, 1);
});

test('closing a confirm dialog returns focus to the focused opener', async () => {
    const harness = createFormBrowserHarness();
    harness.loadScripts([]);
    const opener = harness.registerElement('button', { id: 'opener' });
    harness.document.body.appendChild(opener);
    opener.focus();
    const pending = harness.context.workbench.confirmDialog.open({ title: 'Remove?', body: 'x', confirmLabel: 'Remove' });
    const dialog = harness.document.querySelectorAll('dialog')[0];
    assert.notEqual(harness.document.activeElement, opener, 'Cancel takes the focus');
    dialog.querySelectorAll('button')[0].click();
    assert.equal(await pending, false);
    assert.equal(harness.document.activeElement, opener);
});

test('a dialog opened by a pressed control that took no focus (Safari) returns focus to that control', async () => {
    const harness = createFormBrowserHarness();
    harness.loadScripts([]);
    const outlet = harness.registerElement('div', { id: 'workbench-outlet', attributes: { tabindex: '-1' } });
    const label = harness.registerElement('label');
    const input = harness.registerElement('input', { id: 'create', type: 'button' });
    label.control = input;
    const icon = harness.registerElement('span');
    label.appendChild(icon);
    label.appendChild(input);
    outlet.appendChild(label);
    harness.document.body.appendChild(outlet);

    harness.window.trigger('pointerdown', { target: icon });
    outlet.focus();
    const pending = harness.context.workbench.confirmDialog.open({ title: 'Use?', body: 'x', confirmLabel: 'Use' });
    harness.document.querySelectorAll('dialog')[0].querySelectorAll('button')[1].click();
    assert.equal(await pending, true);
    assert.equal(harness.document.activeElement, input, 'the label\'s control, not the page around it');

    // A key press since the last press means the keyboard opened the dialog: focus goes back where it was.
    harness.window.trigger('pointerdown', { target: icon });
    harness.window.trigger('keydown', { key: 'Enter' });
    const field = harness.registerElement('input', { id: 'field', type: 'text' });
    outlet.appendChild(field);
    field.focus();
    const next = harness.context.workbench.confirmDialog.open({ title: 'Use?', body: 'x', confirmLabel: 'Use' });
    harness.document.querySelectorAll('dialog')[0].querySelectorAll('button')[0].click();
    assert.equal(await next, false);
    assert.equal(harness.document.activeElement, field);
});

test('the editor full-screen toggle focuses its editor and Escape anywhere leaves full screen', () => {
    const harness = createFormBrowserHarness();
    harness.loadScripts([]);
    const calls = [];
    const options = { fullScreen: false };
    const wrapper = harness.registerElement('div', { className: 'CodeMirror' });
    wrapper.CodeMirror = {
        focus: () => calls.push('focus'),
        getOption: (name) => options[name],
        setOption: (name, value) => { options[name] = value; calls.push(name + '=' + value); }
    };
    const toggle = harness.registerElement('div', { className: 'svgImg yasqe_fullscreenBtn' });
    const icon = harness.registerElement('span');
    toggle.appendChild(icon);
    wrapper.appendChild(toggle);
    harness.document.body.appendChild(wrapper);

    // YASQE's own click handler turns full screen on; the page's listener then focuses the editor.
    options.fullScreen = true;
    wrapper.classList.add('CodeMirror-fullscreen');
    harness.window.trigger('click', { target: icon });
    assert.deepEqual(calls, ['focus']);

    let prevented = false;
    harness.window.trigger('keydown', { key: 'Escape', target: harness.document.body, defaultPrevented: false,
        preventDefault: () => { prevented = true; } });
    assert.deepEqual(calls, ['focus', 'fullScreen=false', 'focus']);
    assert.equal(prevented, true);

    // An Escape the editor already used (it prevents the default) changes nothing.
    options.fullScreen = true;
    harness.window.trigger('keydown', { key: 'Escape', target: harness.document.body, defaultPrevented: true,
        preventDefault: () => { } });
    assert.equal(options.fullScreen, true);
});
